import{_ as e,o as t,c as r,a3 as h}from"./chunks/framework.BlfGB29P.js";const u=JSON.parse('{"title":"模型能力与幻觉","description":"理解模型能力来源、泛化、上下文学习、知识与推理限制、幻觉类型、不确定性，以及应用侧验证责任。","frontmatter":{"title":"模型能力与幻觉","description":"理解模型能力来源、泛化、上下文学习、知识与推理限制、幻觉类型、不确定性，以及应用侧验证责任。","verified_at":"2026-07-28","sources":["https://arxiv.org/abs/2005.14165","https://arxiv.org/abs/2307.09288","https://arxiv.org/abs/2311.05232","https://www.nist.gov/itl/ai-risk-management-framework"],"article":{"type":"concept","structure":"concept"}},"headers":[],"relativePath":"py-agent/foundations/model-principles/model-capabilities-hallucination.md","filePath":"py-agent/foundations/model-principles/model-capabilities-hallucination.md","lastUpdated":1785291406000}'),i={name:"py-agent/foundations/model-principles/model-capabilities-hallucination.md"};function o(l,a,d,n,s,c){return t(),r("div",null,[...a[0]||(a[0]=[h('<h1 id="模型能力与幻觉" tabindex="-1">模型能力与幻觉 <a class="header-anchor" href="#模型能力与幻觉" aria-label="Permalink to &quot;模型能力与幻觉&quot;">​</a></h1><blockquote><p>作者：codex-gpt-sol-5.6</p></blockquote><p>大语言模型可以用同一套参数完成问答、摘要、翻译、代码和分类，因为预训练学到了可迁移的语言与任务模式，后训练又让模型能从指令和示例中选择适当行为。但模型的基本输出仍是条件概率生成：它擅长产生与上下文相容的内容，却没有内建的事实数据库、业务权限或正确性证明。</p><p>“幻觉”不是一种单一异常。本章按输出与可验证目标之间的偏差分类，并说明应用应在哪一层承担责任。</p><h2 id="_1-能力从哪里来" tabindex="-1">1. 能力从哪里来 <a class="header-anchor" href="#_1-能力从哪里来" aria-label="Permalink to &quot;1. 能力从哪里来&quot;">​</a></h2><h3 id="_1-1-预训练学习广泛模式" tabindex="-1">1.1 预训练学习广泛模式 <a class="header-anchor" href="#_1-1-预训练学习广泛模式" aria-label="Permalink to &quot;1.1 预训练学习广泛模式&quot;">​</a></h3><p>大规模语言建模要求模型压缩有助于预测文本的结构。语法、语义、常识关联、代码惯例和文档格式都可能成为可复用表示。规模、数据、架构和训练方法共同影响能力，不能只用参数量解释。</p><h3 id="_1-2-后训练使能力更容易被调用" tabindex="-1">1.2 后训练使能力更容易被调用 <a class="header-anchor" href="#_1-2-后训练使能力更容易被调用" aria-label="Permalink to &quot;1.2 后训练使能力更容易被调用&quot;">​</a></h3><p>监督示范和偏好数据教模型把已有能力组织成助手响应，例如遵循任务、拒绝不当请求、输出指定格式。后训练既可能创造新行为，也可能主要让预训练中潜在能力更稳定地显现。</p><h3 id="_1-3-上下文提供临时任务定义" tabindex="-1">1.3 上下文提供临时任务定义 <a class="header-anchor" href="#_1-3-上下文提供临时任务定义" aria-label="Permalink to &quot;1.3 上下文提供临时任务定义&quot;">​</a></h3><p>模型能从当前 Prompt 中识别说明、示例和新标签映射，而无需更新参数，这称为上下文学习。它是运行时条件化：示例离开上下文后不会自动成为永久知识。</p><h2 id="_2-泛化与任务表现" tabindex="-1">2. 泛化与任务表现 <a class="header-anchor" href="#_2-泛化与任务表现" aria-label="Permalink to &quot;2. 泛化与任务表现&quot;">​</a></h2><h3 id="_2-1-泛化是对未见输入的有效表现" tabindex="-1">2.1 泛化是对未见输入的有效表现 <a class="header-anchor" href="#_2-1-泛化是对未见输入的有效表现" aria-label="Permalink to &quot;2.1 泛化是对未见输入的有效表现&quot;">​</a></h3><p>模型不只复述训练样本，还能组合已学模式处理新措辞和新组合。是否真正泛化，必须通过与训练数据独立、覆盖真实变化的评测判断。</p><h3 id="_2-2-相似任务会迁移-也会误迁移" tabindex="-1">2.2 相似任务会迁移，也会误迁移 <a class="header-anchor" href="#_2-2-相似任务会迁移-也会误迁移" aria-label="Permalink to &quot;2.2 相似任务会迁移，也会误迁移&quot;">​</a></h3><p>模型可能把熟悉格式套到新任务上，这有时是能力，有时是错误。例如看到法律式文本就补出不存在的条款编号，正是语言模式迁移超过事实证据的结果。</p><h3 id="_2-3-能力不是全局常量" tabindex="-1">2.3 能力不是全局常量 <a class="header-anchor" href="#_2-3-能力不是全局常量" aria-label="Permalink to &quot;2.3 能力不是全局常量&quot;">​</a></h3><p>同一模型在不同语言、领域、上下文长度、输出格式和提示方式下表现不同。说“模型会数学”或“模型支持长上下文”过于粗糙；应用需要明确题型、难度、数据分布和成功标准。</p><h2 id="_3-知识边界" tabindex="-1">3. 知识边界 <a class="header-anchor" href="#_3-知识边界" aria-label="Permalink to &quot;3. 知识边界&quot;">​</a></h2><h3 id="_3-1-参数知识可能过时或不完整" tabindex="-1">3.1 参数知识可能过时或不完整 <a class="header-anchor" href="#_3-1-参数知识可能过时或不完整" aria-label="Permalink to &quot;3.1 参数知识可能过时或不完整&quot;">​</a></h3><p>模型训练有时间和数据覆盖边界。即使某事实在训练前已存在，也不保证被充分学习、准确保留或在当前措辞下正确调用。</p><h3 id="_3-2-来源记忆不可靠" tabindex="-1">3.2 来源记忆不可靠 <a class="header-anchor" href="#_3-2-来源记忆不可靠" aria-label="Permalink to &quot;3.2 来源记忆不可靠&quot;">​</a></h3><p>模型可能记住内容关联，却不能稳定恢复精确出处。要求引用时，它可能组合合理的作者、标题、期刊和年份，形成不存在的引用。引用必须通过真实文献库或链接解析验证。</p><h3 id="_3-3-私有和实时事实需要外部系统" tabindex="-1">3.3 私有和实时事实需要外部系统 <a class="header-anchor" href="#_3-3-私有和实时事实需要外部系统" aria-label="Permalink to &quot;3.3 私有和实时事实需要外部系统&quot;">​</a></h3><p>账户状态、库存、当天新闻和企业内部规则不应依赖参数猜测。应用应调用权威 API、数据库或检索系统，并明确结果的时间、权限与来源。</p><h2 id="_4-推理边界" tabindex="-1">4. 推理边界 <a class="header-anchor" href="#_4-推理边界" aria-label="Permalink to &quot;4. 推理边界&quot;">​</a></h2><h3 id="_4-1-生成过程可以实现多步计算" tabindex="-1">4.1 生成过程可以实现多步计算 <a class="header-anchor" href="#_4-1-生成过程可以实现多步计算" aria-label="Permalink to &quot;4.1 生成过程可以实现多步计算&quot;">​</a></h3><p>模型能够产生中间步骤、分解问题并组合规则，在许多任务上表现出推理能力。增加计算预算、提供工具或结构化步骤可能改善结果。</p><h3 id="_4-2-中间过程仍可能建立在错误上" tabindex="-1">4.2 中间过程仍可能建立在错误上 <a class="header-anchor" href="#_4-2-中间过程仍可能建立在错误上" aria-label="Permalink to &quot;4.2 中间过程仍可能建立在错误上&quot;">​</a></h3><p>一条推导可以形式流畅但第一步就读错条件。后续 Token 会继续条件化于先前错误，因此“步骤多”和“解释详细”都不是正确证明。</p><h3 id="_4-3-可执行验证优于语言自证" tabindex="-1">4.3 可执行验证优于语言自证 <a class="header-anchor" href="#_4-3-可执行验证优于语言自证" aria-label="Permalink to &quot;4.3 可执行验证优于语言自证&quot;">​</a></h3><p>算术可交给计算器，代码可运行测试，Schema 可由解析器验证，约束优化可由求解器检查。让同一个模型再次说“我确认正确”通常只是另一次概率生成。</p><h2 id="_5-什么是幻觉" tabindex="-1">5. 什么是幻觉 <a class="header-anchor" href="#_5-什么是幻觉" aria-label="Permalink to &quot;5. 什么是幻觉&quot;">​</a></h2><p>在应用语境中，可以把幻觉定义为：模型生成了看似有根据、但与给定来源、外部事实、任务输入或可验证规则不一致的内容。重点不是模型内部是否“相信”，而是输出是否违反可检查目标。</p><h3 id="_5-1-外部事实幻觉" tabindex="-1">5.1 外部事实幻觉 <a class="header-anchor" href="#_5-1-外部事实幻觉" aria-label="Permalink to &quot;5.1 外部事实幻觉&quot;">​</a></h3><p>输出与现实或权威数据不符，例如虚构人物经历、过期价格或错误医学信息。验证需要可靠外部来源。</p><h3 id="_5-2-来源归属幻觉" tabindex="-1">5.2 来源归属幻觉 <a class="header-anchor" href="#_5-2-来源归属幻觉" aria-label="Permalink to &quot;5.2 来源归属幻觉&quot;">​</a></h3><p>内容也许合理，但引用、链接、页码或原话不存在。它与一般事实错误分开，因为验证方法是解析并核对来源。</p><h3 id="_5-3-输入不一致幻觉" tabindex="-1">5.3 输入不一致幻觉 <a class="header-anchor" href="#_5-3-输入不一致幻觉" aria-label="Permalink to &quot;5.3 输入不一致幻觉&quot;">​</a></h3><p>摘要加入原文没有的信息、从表格抄错数字、把用户明确条件反过来。这类错误可以直接相对当前输入验证，不必查询世界知识。</p><h3 id="_5-4-结构与协议错误" tabindex="-1">5.4 结构与协议错误 <a class="header-anchor" href="#_5-4-结构与协议错误" aria-label="Permalink to &quot;5.4 结构与协议错误&quot;">​</a></h3><p>模型声称输出 JSON，却漏字段、类型错误或夹带正文。它更适合称为契约失败，但在产品中同样表现为“模型编造了不可用结果”。应由 Schema 验证器处理，而不是人工猜测修复。</p><h2 id="_6-幻觉为什么发生" tabindex="-1">6. 幻觉为什么发生 <a class="header-anchor" href="#_6-幻觉为什么发生" aria-label="Permalink to &quot;6. 幻觉为什么发生&quot;">​</a></h2><h3 id="_6-1-训练目标奖励合理续写" tabindex="-1">6.1 训练目标奖励合理续写 <a class="header-anchor" href="#_6-1-训练目标奖励合理续写" aria-label="Permalink to &quot;6.1 训练目标奖励合理续写&quot;">​</a></h3><p>语言建模奖励对数据分布的预测。面对缺失信息，生成一个常见且连贯的模式可能比停下来承认未知更符合局部概率。</p><h3 id="_6-2-上下文可能缺失、冲突或含误导" tabindex="-1">6.2 上下文可能缺失、冲突或含误导 <a class="header-anchor" href="#_6-2-上下文可能缺失、冲突或含误导" aria-label="Permalink to &quot;6.2 上下文可能缺失、冲突或含误导&quot;">​</a></h3><p>如果输入没有答案，模型可能用参数关联补全；如果多个来源冲突，它可能未经声明地选择或混合；如果用户给出错误前提，模型可能顺着前提继续生成。</p><h3 id="_6-3-解码会放大路径依赖" tabindex="-1">6.3 解码会放大路径依赖 <a class="header-anchor" href="#_6-3-解码会放大路径依赖" aria-label="Permalink to &quot;6.3 解码会放大路径依赖&quot;">​</a></h3><p>采样可能选择低概率但错误的早期 Token，后续输出再围绕它保持一致。确定解码能减少随机差异，却不能消除原始分布中的系统性错误。</p><h3 id="_6-4-任务超出稳定能力范围" tabindex="-1">6.4 任务超出稳定能力范围 <a class="header-anchor" href="#_6-4-任务超出稳定能力范围" aria-label="Permalink to &quot;6.4 任务超出稳定能力范围&quot;">​</a></h3><p>陌生领域、复杂组合推理、过长上下文和精确引用都会提高失败概率。模型很少能自行可靠判断输入是否落在能力边界内。</p><h2 id="_7-不确定性" tabindex="-1">7. 不确定性 <a class="header-anchor" href="#_7-不确定性" aria-label="Permalink to &quot;7. 不确定性&quot;">​</a></h2><h3 id="_7-1-语言上的自信不是校准分数" tabindex="-1">7.1 语言上的自信不是校准分数 <a class="header-anchor" href="#_7-1-语言上的自信不是校准分数" aria-label="Permalink to &quot;7.1 语言上的自信不是校准分数&quot;">​</a></h3><p>“我确定”“答案是”属于生成文本，可能只是常见表达。要求模型给 0 到 100 的置信度，也不保证这个数字与真实错误率匹配。</p><h3 id="_7-2-模型可能不知道自己不知道" tabindex="-1">7.2 模型可能不知道自己不知道 <a class="header-anchor" href="#_7-2-模型可能不知道自己不知道" aria-label="Permalink to &quot;7.2 模型可能不知道自己不知道&quot;">​</a></h3><p>参数中没有显式、完备的知识目录供运行时查询。模型能学会在某些模式下拒答或表达不确定，但这种行为仍需在具体领域校准。</p><h3 id="_7-3-可操作的不确定性来自系统证据" tabindex="-1">7.3 可操作的不确定性来自系统证据 <a class="header-anchor" href="#_7-3-可操作的不确定性来自系统证据" aria-label="Permalink to &quot;7.3 可操作的不确定性来自系统证据&quot;">​</a></h3><p>应用可以组合来源是否命中、数据新鲜度、Schema 是否通过、规则检查结果、多个样本是否一致和人工复核状态。这些信号各有含义，不应压成一个未经校准的“模型置信度”。</p><h2 id="_8-指令遵循、事实与业务正确性" tabindex="-1">8. 指令遵循、事实与业务正确性 <a class="header-anchor" href="#_8-指令遵循、事实与业务正确性" aria-label="Permalink to &quot;8. 指令遵循、事实与业务正确性&quot;">​</a></h2><p>三者是不同维度：</p><table tabindex="0"><thead><tr><th>维度</th><th>问题</th><th>典型验证</th></tr></thead><tbody><tr><td>指令遵循</td><td>是否完成了要求的任务与格式？</td><td>Schema、任务断言、人工标准</td></tr><tr><td>事实正确</td><td>陈述是否与来源或现实一致？</td><td>数据库、检索来源、事实核验</td></tr><tr><td>业务正确</td><td>结果是否符合权限、状态与规则？</td><td>确定性业务代码、授权系统</td></tr></tbody></table><p>模型可能格式正确但事实错误，也可能事实正确却执行了无权限操作。只评一个维度会掩盖其他风险。</p><h2 id="_9-应用侧验证策略" tabindex="-1">9. 应用侧验证策略 <a class="header-anchor" href="#_9-应用侧验证策略" aria-label="Permalink to &quot;9. 应用侧验证策略&quot;">​</a></h2><h3 id="_9-1-先按风险决定验证强度" tabindex="-1">9.1 先按风险决定验证强度 <a class="header-anchor" href="#_9-1-先按风险决定验证强度" aria-label="Permalink to &quot;9.1 先按风险决定验证强度&quot;">​</a></h3><table tabindex="0"><thead><tr><th>任务</th><th>可接受策略</th></tr></thead><tbody><tr><td>创意草稿</td><td>人工选择，容许多样性</td></tr><tr><td>文档分类</td><td>Schema 校验 + 标注样例评测</td></tr><tr><td>基于资料的摘要</td><td>逐条与来源对齐 + 引用位置</td></tr><tr><td>金额计算</td><td>模型提取输入 + 确定性代码计算</td></tr><tr><td>执行外部操作</td><td>权限校验 + 参数校验 + 用户确认 + 审计</td></tr></tbody></table><p>风险越高，越不能让自然语言输出直接驱动副作用。</p><h3 id="_9-2-把可验证部分外移" tabindex="-1">9.2 把可验证部分外移 <a class="header-anchor" href="#_9-2-把可验证部分外移" aria-label="Permalink to &quot;9.2 把可验证部分外移&quot;">​</a></h3><p>模型适合处理含糊语言、候选生成和语义转换；解析、枚举、范围、权限、算术、唯一性和事务约束应交给确定性组件。</p><h3 id="_9-3-失败必须可见" tabindex="-1">9.3 失败必须可见 <a class="header-anchor" href="#_9-3-失败必须可见" aria-label="Permalink to &quot;9.3 失败必须可见&quot;">​</a></h3><p>验证失败应产生明确错误状态、重试决策或人工复核任务。偷偷删除错误字段、用默认值补齐或把解析失败当空结果，会把模型不确定性变成业务数据污染。</p><h2 id="_10-不能单独解决幻觉的方法" tabindex="-1">10. 不能单独解决幻觉的方法 <a class="header-anchor" href="#_10-不能单独解决幻觉的方法" aria-label="Permalink to &quot;10. 不能单独解决幻觉的方法&quot;">​</a></h2><h3 id="_10-1-更长-prompt" tabindex="-1">10.1 更长 Prompt <a class="header-anchor" href="#_10-1-更长-prompt" aria-label="Permalink to &quot;10.1 更长 Prompt&quot;">​</a></h3><p>更多说明有时改善任务理解，也可能引入冲突和噪声。它不能提供缺失的权威事实。</p><h3 id="_10-2-降低-temperature" tabindex="-1">10.2 降低 temperature <a class="header-anchor" href="#_10-2-降低-temperature" aria-label="Permalink to &quot;10.2 降低 temperature&quot;">​</a></h3><p>它减少采样差异，不会修复模型最高概率答案本身的错误。</p><h3 id="_10-3-让模型自我检查" tabindex="-1">10.3 让模型自我检查 <a class="header-anchor" href="#_10-3-让模型自我检查" aria-label="Permalink to &quot;10.3 让模型自我检查&quot;">​</a></h3><p>第二次生成可发现部分疏漏，但也可能重复或合理化同一错误。自检应与独立数据、工具或不同验证机制结合。</p><h3 id="_10-4-只接入检索" tabindex="-1">10.4 只接入检索 <a class="header-anchor" href="#_10-4-只接入检索" aria-label="Permalink to &quot;10.4 只接入检索&quot;">​</a></h3><p>检索可以提供证据，模型仍可能忽略、误读或错误引用。检索质量、上下文组织、引用对齐和结果验证都需要评测。</p><h2 id="_11-常见误解" tabindex="-1">11. 常见误解 <a class="header-anchor" href="#_11-常见误解" aria-label="Permalink to &quot;11. 常见误解&quot;">​</a></h2><h3 id="_11-1-模型越大就不会幻觉" tabindex="-1">11.1 “模型越大就不会幻觉” <a class="header-anchor" href="#_11-1-模型越大就不会幻觉" aria-label="Permalink to &quot;11.1 “模型越大就不会幻觉”&quot;">​</a></h3><p>规模可能改善许多能力，也可能让错误表达更有说服力。是否满足任务标准必须实测。</p><h3 id="_11-2-拒答越多越安全" tabindex="-1">11.2 “拒答越多越安全” <a class="header-anchor" href="#_11-2-拒答越多越安全" aria-label="Permalink to &quot;11.2 “拒答越多越安全”&quot;">​</a></h3><p>过度拒绝会损害正常任务。安全需要按风险区分允许、拒绝、确认和人工复核，而不是单一拒答率。</p><h3 id="_11-3-输出有引用就可追溯" tabindex="-1">11.3 “输出有引用就可追溯” <a class="header-anchor" href="#_11-3-输出有引用就可追溯" aria-label="Permalink to &quot;11.3 “输出有引用就可追溯”&quot;">​</a></h3><p>引用本身也可能被生成。必须确认来源存在、内容匹配且确实支持对应陈述。</p><h2 id="_12-自测" tabindex="-1">12. 自测 <a class="header-anchor" href="#_12-自测" aria-label="Permalink to &quot;12. 自测&quot;">​</a></h2><ol><li>预训练、后训练和上下文学习分别怎样贡献能力？</li><li>外部事实幻觉、来源归属幻觉和输入不一致有何区别？</li><li>为什么模型口头置信度不能直接作为业务概率？</li><li>指令遵循、事实正确和业务正确分别应由什么验证？</li><li>哪些任务应该把最终计算或副作用交给确定性系统？</li></ol><p>能够先定义可验证目标，再按“输入证据、模型输出、结构契约、外部事实、业务规则”逐层检查，就把幻觉从模糊印象转化成可工程化处理的风险。</p>',89)])])}const _=e(i,[["render",o]]);export{u as __pageData,_ as default};
